import*as T from"three";import{STLLoader as L}from"three/examples/jsm/loaders/STLLoader.js";import{OrbitControls as O}from"three/examples/jsm/controls/OrbitControls.js";
const D={"mdf_bottom": ["", "#c9a27a", 0.35], "mdf_side_L": ["", "#c9a27a", 0.35], "mdf_side_R": ["", "#c9a27a", 0.35], "mdf_back": ["", "#c9a27a", 0.35], "mdf_top": ["", "#c9a27a", 0.35], "mdf_front": ["", "#c9a27a", 0.35], "mdf_shelf": ["", "#c9a27a", 0.35], "base": ["", "#8fa3b8", 1], "disc": ["", "#e8a33d", 1], "lid": ["", "#6fbf8f", 0.8], "motor": ["", "#c0c0c8", 1], "uln2003": ["", "#2e7d32", 1], "esp32": ["", "#1565c0", 1], "rc522": ["", "#1976d2", 1], "ir_rx": ["", "#333", 1], "buzzer": ["", "#222", 1], "bottle": ["", "#9fd3ff", 0.3], "cup": ["", "#ffffff", 0.6]};const r=new T.WebGLRenderer({antialias:true});r.setPixelRatio(devicePixelRatio);document.body.appendChild(r.domElement);const s=new T.Scene();s.background=new T.Color(0x1e1e22);
const c=new T.PerspectiveCamera(40,1,1,3000);c.up.set(0,0,1);c.position.set(330,-380,330);const o=new O(c,r.domElement);o.target.set(0,0,130);
s.add(new T.HemisphereLight(0xffffff,0x444455,1.2));const l=new T.DirectionalLight(0xffffff,1.4);l.position.set(200,-300,500);s.add(l);const ld=new L(),mdf=[];
for(const k in D){const[b,cl,op]=D[k];const g=ld.parse(Uint8Array.from(atob(b),x=>x.charCodeAt(0)).buffer);g.computeVertexNormals();const m=new T.Mesh(g,new T.MeshStandardMaterial({color:cl,roughness:.7,transparent:op<1,opacity:op,depthWrite:op>=.5}));s.add(m);if(k.startsWith("mdf"))mdf.push(m)}
let t=1;const bt=document.getElementById("b");bt.onclick=()=>{t^=1;mdf.forEach(m=>{m.material.opacity=t?.35:1;m.material.transparent=!!t;m.material.depthWrite=!t;m.material.needsUpdate=true});bt.textContent=t?"MDFを不透明に":"MDFを透明に"};
function rs(){r.setSize(innerWidth,innerHeight);c.aspect=innerWidth/innerHeight;c.updateProjectionMatrix()}addEventListener("resize",rs);rs();(function a(){requestAnimationFrame(a);o.update();r.render(s,c)})();